import React, { useState } from "react";

/* Design system La Répét' (v2) : jetons, logos, composants de base. */

const T = {
  // Bleu principal = couleur DOMINANTE (~60%)
  primary: "#386097", primaryDk: "#2C4D7C", primaryLt: "#4A72A8",
  // Bleu clair = secondaire (~20%)
  blue: "#3893CD", blueDk: "#2E7CB0",
  // Orange = ACCENT rare (~10%) : CTA, progression, objectif
  orange: "#C25700", orangeDk: "#A84B00",
  // Violet = IA / simulation uniquement (~10%)
  violet: "#5C4BB9", lavender: "#736BDE",
  // Sémantique
  success: "#41C77A", successBg: "#E9F8F0",
  error: "#FF5A72", errorBg: "#FFECEF",
  warning: "#FFB547", warningBg: "#FFF6E8",
  // Neutres
  bg: "#F8FAFC", surface: "#FFFFFF",
  navy: "#1B3A66", ink: "#1B3A66", body: "#4A5568", muted: "#64748B", faint: "#A4AFBF",
  line: "#E7EBF2", lineLt: "#F0F3F8",
};
// Gradients spécialisés (v2)
const GRAD_MAIN = `linear-gradient(135deg, ${T.blue} 0%, ${T.violet} 100%)`;            // principal : bleu clair → violet
const GRAD_PREMIUM = `linear-gradient(135deg, ${T.primary} 0%, ${T.blue} 50%, ${T.violet} 100%)`; // hero
const GRAD_COACH = `linear-gradient(135deg, ${T.blue} 0%, ${T.orange} 100%)`;          // scores : apprentissage → progression
const GRAD_AI = `linear-gradient(135deg, ${T.blue} 0%, ${T.lavender} 100%)`;           // bouton IA
// alias rétro-compat (anciens noms utilisés dans le code)
const GRAD = GRAD_PREMIUM;
const GRAD_SOFT = `linear-gradient(135deg, ${T.primary}14, ${T.violet}12)`;
const GRAD_AI_SOFT = `linear-gradient(135deg, ${T.blue}16, ${T.lavender}16)`;
const FD = "'Manrope', 'Segoe UI', sans-serif";   // display / heading
const FB = "'Inter', 'Segoe UI', sans-serif";     // body / ui
const FM = "'JetBrains Mono', monospace";          // chiffres
const RAD = { xs: 6, sm: 10, md: 16, lg: 24, xl: 32, pill: 999 };
const SH = { xs: "0 2px 6px rgba(27,58,102,.05)", sm: "0 8px 20px rgba(27,58,102,.07)", lg: "0 20px 60px rgba(27,58,102,.10)" };
const sp = n => n * 4;


/* ─── LOGOS (images officielles fournies, embarquées en base64) ─── */

const LOGO_SYM = "data:image/png;base64,";
const LOGO_WORD = "data:image/png;base64,";

// Symbole bulles La Répét' (image officielle)
function RepetMark({ s = 36 }) {
  return <img src={LOGO_SYM} alt="" aria-hidden style={{ width: s, height: "auto", display: "block" }} />;
}

// Logo complet La Répét' : symbole + wordmark "La Répét"
function RepetLogo({ s = 22, dark = false, tagline = true }) {
  const sub = dark ? "rgba(255,255,255,.6)" : T.muted;
  // hauteur du wordmark calée sur la taille de police demandée
  const wordH = s * 2.0;
  return (
    <div style={{ display: "flex", alignItems: "center", gap: s * 0.5 }}>
      <img src={LOGO_SYM} alt="La Répét'" style={{ height: s * 2.1, width: "auto", display: "block" }} />
      <div style={{ display: "flex", flexDirection: "column", gap: tagline ? 3 : 0 }}>
        <img src={LOGO_WORD} alt="La Répét'" style={{ height: wordH, width: "auto", display: "block", filter: dark ? "brightness(0) invert(1)" : "none" }} />
        {tagline && <div style={{ font: `500 ${s * 0.44}px ${FB}`, color: sub, letterSpacing: ".01em" }}>Coach IA d'entretien</div>}
      </div>
    </div>
  );
}

// Faux logo d'organisme partenaire (marque blanche, fictif)
function TSMark({ s = 30, dark = false }) {
  const c1 = dark ? "#fff" : "#386097", c2 = "#C25700";
  return (
    <svg width={s} height={s} viewBox="0 0 40 40" fill="none" aria-hidden style={{ display: "block" }}>
      <rect x="3" y="3" width="34" height="34" rx="10" stroke={c1} strokeWidth="3" />
      <path d="M12 26 L18 18 L23 22 L29 13" stroke={c1} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
      <circle cx="29" cy="13" r="3.2" fill={c2} />
    </svg>
  );
}

function TSLogo({ s = 13, dark = false }) {
  const fg = dark ? "#fff" : "#386097", sub = dark ? "rgba(255,255,255,.6)" : "#64748B";
  return (
    <div style={{ display: "flex", alignItems: "center", gap: s * 0.6 }} aria-label="Votre organisme (logo fictif)">
      <TSMark s={s * 2.6} dark={dark} />
      <div style={{ lineHeight: 1.05 }}>
        <div style={{ font: `700 ${s * 1.35}px 'Manrope', sans-serif`, color: fg, letterSpacing: "-.01em" }}>Votre organisme</div>
        <div style={{ font: `500 ${s * 0.8}px 'Inter', sans-serif`, color: sub, marginTop: 2 }}>Logo fictif · marque blanche</div>
      </div>
    </div>
  );
}

/* halo lumineux décoratif */
function Halo({ style }) {
  return <div style={{ position: "absolute", borderRadius: "50%", filter: "blur(60px)", pointerEvents: "none", ...style }} />;
}

/* ─── PRIMITIVES ───────────────────────────────────────────────────────── */

function Tag({ children, tone = "blue" }) {
  const m = {
    primary: [T.primary, `${T.primary}12`], blue: [T.blueDk, `${T.blue}16`],
    indigo: [T.primary, `${T.primary}12`], // alias rétro-compat
    ai: [T.violet, `${T.violet}14`], violet: [T.violet, `${T.violet}14`], lavender: [T.violet, `${T.violet}14`],
    orange: [T.orange, `${T.orange}14`],
    success: [T.success, T.successBg], warning: ["#B5791A", T.warningBg], error: [T.error, T.errorBg], muted: [T.muted, T.lineLt],
  }[tone];
  return (
    <span style={{ font: `600 11px ${FB}`, letterSpacing: ".02em", color: m[0], background: m[1], padding: "5px 11px", borderRadius: RAD.pill, display: "inline-flex", alignItems: "center", gap: 5 }}>{children}</span>
  );
}

function Btn({ children, onClick, kind = "primary", size = "md", disabled, full }) {
  const [hov, setHov] = useState(false);
  const kinds = {
    // Primaire : bleu principal plein, léger dégradé bleu→violet au survol
    primary: { background: hov ? GRAD_MAIN : T.primary, color: "#fff", border: "none", boxShadow: hov ? "0 8px 22px rgba(56,96,151,.32)" : "0 4px 12px rgba(56,96,151,.20)" },
    // Bouton IA : vrai dégradé bleu→violet, identifiable
    ai: { background: GRAD_AI, color: "#fff", border: "none", boxShadow: hov ? "0 8px 24px rgba(92,75,185,.34)" : "0 4px 14px rgba(92,75,185,.24)" },
    // Objectif atteint : orange, rare et très visible
    objective: { background: T.orange, color: "#fff", border: "none", boxShadow: hov ? "0 8px 22px rgba(194,87,0,.30)" : "0 4px 12px rgba(194,87,0,.20)" },
    blue: { background: T.blue, color: "#fff", border: "none" },
    dark: { background: T.primary, color: "#fff", border: "none" },
    // Secondaire : blanc, bordure bleue, texte bleu
    secondary: { background: "#fff", color: T.primary, border: `1.5px solid ${hov ? T.primary : T.primaryLt}` },
    ghost: { background: "transparent", color: T.primary, border: "none" },
    ghostDark: { background: "rgba(255,255,255,.12)", color: "#fff", border: "1px solid rgba(255,255,255,.3)" },
    danger: { background: T.error, color: "#fff", border: "none" },
  }[kind];
  const sizes = { sm: { p: "9px 16px", f: 13, h: 38 }, md: { p: "0 22px", f: 14.5, h: 48 }, lg: { p: "0 28px", f: 15.5, h: 54 } }[size];
  return (
    <button onClick={disabled ? undefined : onClick} disabled={disabled}
      onMouseEnter={() => !disabled && setHov(true)} onMouseLeave={() => setHov(false)}
      style={{
        font: `600 ${sizes.f}px ${FB}`, height: sizes.h, padding: sizes.p, borderRadius: RAD.md,
        cursor: disabled ? "not-allowed" : "pointer", transition: "all .2s",
        width: full ? "100%" : "auto", opacity: disabled ? 0.45 : 1,
        transform: hov && !disabled ? "translateY(-1.5px)" : "none",
        display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 8, ...kinds,
      }}>
      {children}
    </button>
  );
}

function Card({ children, style, pad = 24, hover, onClick, topbar }) {
  const [h, setH] = useState(false);
  return (
    <div onClick={onClick} onMouseEnter={() => setH(true)} onMouseLeave={() => setH(false)} style={{
      position: "relative", background: T.surface, border: `1px solid ${T.line}`, borderRadius: RAD.lg, padding: pad,
      boxShadow: hover && h ? SH.lg : SH.xs, transition: "box-shadow .2s, transform .2s",
      transform: hover && h ? "translateY(-3px)" : "none", cursor: onClick ? "pointer" : "default",
      overflow: topbar ? "hidden" : undefined, ...style,
    }}>
      {topbar && <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 4, background: topbar === "coach" ? GRAD_COACH : topbar === "ai" ? GRAD_AI : GRAD_MAIN }} />}
      {children}
    </div>
  );
}

const Back = ({ onClick }) => (
  <button onClick={onClick} style={{ font: `500 14px ${FB}`, color: T.muted, background: "none", border: "none", cursor: "pointer", padding: "8px 4px" }}>← Retour</button>
);

const Icon = ({ d, s = 20, c = "currentColor", sw = 2 }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={sw} strokeLinecap="round" strokeLinejoin="round">{d}</svg>
);
const I = {
  lock: <><rect x="3" y="11" width="18" height="11" rx="2" /><path d="M7 11V7a5 5 0 0 1 10 0v4" /></>,
  shield: <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" />,
  sparkle: <><path d="M12 3v18M3 12h18" /><path d="M5.6 5.6l12.8 12.8M18.4 5.6L5.6 18.4" /></>,
  play: <polygon points="6 3 20 12 6 21 6 3" />,
  check: <polyline points="20 6 9 17 4 12" />,
  arrow: <><line x1="5" y1="12" x2="19" y2="12" /><polyline points="12 5 19 12 12 19" /></>,
  redo: <><polyline points="1 4 1 10 7 10" /><path d="M3.5 15a9 9 0 1 0 2.1-9.4L1 10" /></>,
  user: <><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" /><circle cx="12" cy="7" r="4" /></>,
  send: <><line x1="22" y1="2" x2="11" y2="13" /><polygon points="22 2 15 22 11 13 2 9 22 2" /></>,
  trash: <><polyline points="3 6 5 6 21 6" /><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" /><path d="M10 11v6M14 11v6" /><path d="M9 6V4h6v2" /></>,
  copy: <><rect x="9" y="9" width="13" height="13" rx="2" /><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" /></>,
  plus: <><line x1="12" y1="5" x2="12" y2="19" /><line x1="5" y1="12" x2="19" y2="12" /></>,
  pause: <><rect x="6" y="4" width="4" height="16" /><rect x="14" y="4" width="4" height="16" /></>,
  print: <><polyline points="6 9 6 2 18 2 18 9" /><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2" /><rect x="6" y="14" width="12" height="8" /></>,
  note: <><path d="M12 20h9" /><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z" /></>,
  mic: <><rect x="9" y="2" width="6" height="12" rx="3" /><path d="M5 10a7 7 0 0 0 14 0M12 17v5" /></>,
};

/* ─── APP ──────────────────────────────────────────────────────────────── */

const GStyle = () => (
  <style>{`
    @import url('https://fonts.googleapis.com/css2?family=Manrope:wght@500;600;700;800&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@500;700&display=swap');
    *{box-sizing:border-box} body{margin:0}
    html{overflow-y:scroll;scrollbar-gutter:stable}
    ::selection{background:${T.lavender};color:#fff}
    @keyframes up{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
    @keyframes spin{to{transform:rotate(360deg)}}
    @keyframes blink{0%,100%{opacity:1}50%{opacity:.25}}
    @keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}
    @keyframes shimmer{0%{background-position:0% 50%}100%{background-position:100% 50%}}
    .up{animation:up .45s cubic-bezier(.2,.7,.3,1) both}
    input:focus,textarea:focus{outline:none;border-color:${T.blue}!important;box-shadow:0 0 0 4px ${T.blue}22}
    button:focus-visible{outline:2px solid ${T.blue};outline-offset:2px}
    @media (max-width:760px){
      .rp-hide-m{display:none!important}
      .rp-nav{padding:0 16px!important;height:56px!important;gap:10px}
      .rp-tabs{padding:3px!important;gap:2px!important}
      .rp-tabs button{padding:7px 9px!important;font-size:12px!important}
      .rp-hero{grid-template-columns:1fr!important;padding:40px 16px 44px!important;gap:24px!important}
      .rp-h1{font-size:38px!important}
      .rp-h2{font-size:26px!important}
      .rp-h3{font-size:22px!important}
      .rp-section{padding-top:48px!important}
      .rp-stack{grid-template-columns:1fr!important}
      .rp-cta{padding:32px 22px!important}
      .rp-flow{flex-direction:column;gap:18px!important;overflow:visible!important}
      .rp-flow-step{flex:none!important;min-width:0!important}
      .rp-pad{padding-left:16px!important;padding-right:16px!important}
      .rp-split{grid-template-columns:minmax(0,1fr)!important}
      .rp-head{padding:22px 20px!important}
      .rp-card-pad{padding-left:20px!important;padding-right:20px!important}
    }
    @media print{header,footer,.noprint{display:none!important}body{background:#fff}}
    ::-webkit-scrollbar{height:8px;width:8px}::-webkit-scrollbar-thumb{background:${T.line};border-radius:4px}
  `}</style>
);

function Rail({ step, steps }) {
  return (
    <div style={{ display: "flex", alignItems: "center", flexWrap: "wrap", gap: 2 }}>
      {steps.map((s, i) => {
        const done = i < step, now = i === step;
        return (
          <React.Fragment key={i}>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <div style={{ width: 26, height: 26, borderRadius: "50%", flexShrink: 0, display: "grid", placeItems: "center", background: done ? T.success : now ? T.orange : "#fff", border: `2px solid ${done ? T.success : now ? T.orange : T.line}`, color: done || now ? "#fff" : T.faint, font: `700 11px ${FM}`, boxShadow: now ? "0 4px 12px rgba(194,87,0,.28)" : "none", transition: "all .3s" }}>{done ? "✓" : i + 1}</div>
              <span style={{ font: `${now ? 700 : 500} 13px ${FB}`, color: now ? T.orange : done ? T.success : T.faint }}>{s}</span>
            </div>
            {i < steps.length - 1 && <div style={{ width: 22, height: 2, background: done ? T.success : T.line, margin: "0 6px" }} />}
          </React.Fragment>
        );
      })}
    </div>
  );
}

function GradHead({ tag, title, sub, action, soft }) {
  return (
    <div className="rp-head" style={{ position: "relative", overflow: "hidden", padding: "28px 32px", borderRadius: `${RAD.lg}px ${RAD.lg}px 0 0`, background: soft ? GRAD_SOFT : GRAD }}>
      {!soft && <Halo style={{ width: 220, height: 220, background: "rgba(255,255,255,.16)", bottom: -120, right: -30 }} />}
      <div style={{ position: "relative", display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 14, flexWrap: "wrap" }}>
        <div>
          {tag && <div style={{ marginBottom: sp(3) }}><span style={{ font: `600 11px ${FB}`, color: soft ? T.primary : "#fff", background: soft ? "#fff" : "rgba(255,255,255,.2)", padding: "5px 11px", borderRadius: RAD.pill }}>{tag}</span></div>}
          <h1 style={{ font: `800 26px/1.15 ${FD}`, color: soft ? T.navy : "#fff", margin: 0, letterSpacing: "-.02em" }}>{title}</h1>
          {sub && <p style={{ font: `400 14px/1.5 ${FB}`, color: soft ? T.body : "rgba(255,255,255,.85)", margin: "8px 0 0", maxWidth: 520 }}>{sub}</p>}
        </div>
        {action}
      </div>
    </div>
  );
}


export { T, GRAD_MAIN, GRAD_PREMIUM, GRAD_COACH, GRAD_AI, GRAD, GRAD_SOFT, GRAD_AI_SOFT, FD, FB, FM, RAD, SH, sp, RepetMark, RepetLogo, TSMark, TSLogo, Halo, Tag, Btn, Card, Back, Icon, I, GStyle, Rail, GradHead, LOGO_SYM, LOGO_WORD };
